mapper.select:
SELECT * FROM notification
WHERE deleted = 0

    AND type = #{type}


    AND is_urgent = #{isUrgent}


    AND status = #{status}

ORDER BY send_time DESC

SELECT n.* FROM notification n WHERE n.deleted = 0 AND n.status = 'sent' AND ( LOWER(TRIM(COALESCE(n.receiver_type, ''))) = 'all' OR ( n.receiver_ids IS NOT NULL AND TRIM(n.receiver_ids) != '' AND CONCAT(',', REPLACE(REPLACE(n.receiver_ids, ' ', ''), '，', ','), ',') LIKE CONCAT('%,', #{userId}, ',%') )
OR ( LOWER(TRIM(COALESCE(n.receiver_type, ''))) = 'class' AND n.receiver_ids IS NOT NULL AND TRIM(n.receiver_ids) != '' AND FIND_IN_SET( #{className}, REPLACE(REPLACE(n.receiver_ids, ' ', ''), '，', ',') ) > 0 )
) ORDER BY n.send_time DESC
LIMIT #{limit}
